func newEnrollmentCustomizationApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile     string
		flagYes      bool
		flagDryRun   bool
		flagScaffold bool
	)

	cmd := &cobra.Command{
		Use:         "apply",
		Short:       "Create or replace a enrollment-customization by name",
		Annotations: map[string]string{"jamf:api": "pro", "jamf:gateway-privileges": "enrollment-customization:read,enrollment-customization:update"},
		Long: `Create or replace a enrollment-customization. Reads JSON or YAML from --from-file or stdin.

The displayName field in the input is used to check if the resource
already exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.`,
		Example: `  # Apply a enrollment-customization from a JSON file
  jamf-cli pro enrollment-customization apply --from-file enrollment-customization.json

  # Apply a enrollment-customization from a YAML file
  jamf-cli pro enrollment-customization apply --from-file enrollment-customization.yaml

  # Apply from stdin
  cat enrollment-customization.json | jamf-cli pro enrollment-customization apply

  # Apply without replacement confirmation
  jamf-cli pro enrollment-customization apply --from-file enrollment-customization.json --yes

  # Preview what would happen
  jamf-cli pro enrollment-customization apply --from-file enrollment-customization.json --dry-run`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			reqCtx := cmd.Context()
			if flagScaffold {
				return printScaffoldOutput(`{
  "backButtonText": "Back",
  "continueButtonText": "Continue",
  "displayName": "A Panel",
  "ldapGroupAccess": [
    {
      "groupName": "admins",
      "ldapServerId": 1
    }
  ],
  "passwordLabel": "Password",
  "rank": 0,
  "title": "My Ldap Panel",
  "usernameLabel": "Username"
}`, ctx.Output.Format())
			}

			// Read input (JSON or YAML). When file flags are present, empty input
			// is OK — the file-field injector constructs a minimal body.
			data, err := readApplyInput(fromFile)
			if err != nil {
				return err
			}
			if len(data) > 0 {
				data, err = normalizeInputToJSON(data)
				if err != nil {
					return err
				}
			}

			// Extract name from JSON input
			name, err := extractJSONField(data, "displayName")
			if err != nil {
				return fmt.Errorf("input must include a %q field: %w", "displayName", err)
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveNameToIDForApply(reqCtx, ctx.Client, "/v2/enrollment-customizations", "displayName", "id", name, noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create
				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create enrollment-customization %q\n", name)
					return nil
				}
				resp, err := ctx.Client.Do(reqCtx, "POST", "/v1/enrollment-customization/{id}/ldap", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				fmt.Fprintf(os.Stderr, "Created enrollment-customization %q\n", name)
				return ctx.Output.PrintResponse(resp)
			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace enrollment-customization %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("enrollment-customization %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "enrollment-customization %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			updatePath := strings.Replace("/v1/enrollment-customization/{id}/ldap/{panel-id}", "{panel-id}", url.PathEscape(id), 1)
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced enrollment-customization %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON or YAML input file (or pipe to stdin)")
	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")

	return cmd
}
